// app.component.ts
import { Component, OnInit } from '@angular/core';
import { OAuthService } from 'angular-oauth2-oidc';
import { authConfig } from './auth.config';

@Component({
  selector: 'app-root',
  template: `
    <div *ngIf="!isLoggedIn()">
      <h2>Welcome to Simple SSO Demo</h2>
      <button (click)="login()">Login with Google</button>
    </div>
    <div *ngIf="isLoggedIn()">
      <button (click)="logout()">Logout</button>
      <h3>Welcome {{ user?.given_name || user?.name || 'User' }}!</h3>
      <div *ngIf="user">
        <img [src]="user.picture" *ngIf="user.picture" style="border-radius: 50%; width: 100px; height: 100px;" />
        <p>Email: {{ user.email }}</p>
      </div>
      <pre style="text-align: left; background: #f5f5f5; padding: 10px; border-radius: 5px; max-width: 600px; margin: 20px auto; overflow: auto;">
        {{ user | json }}
      </pre>
    </div>
    <div *ngIf="error" class="error">
      {{ error }}
    </div>
  `,
  styles: [`
    .error { 
      color: #d32f2f; 
      background-color: #ffebee;
      padding: 10px;
      border-radius: 4px;
      margin: 10px 0;
      max-width: 600px;
      margin: 20px auto;
    }
    button {
      background-color: #4285f4;
      color: white;
      border: none;
      padding: 10px 20px;
      border-radius: 4px;
      font-size: 16px;
      cursor: pointer;
      margin: 10px 0;
    }
    button:hover {
      background-color: #3367d6;
    }
  `]
})
export class AppComponent implements OnInit {
  user: any;
  error: string = '';

  constructor(private oauthService: OAuthService) {
    // Configure the OAuthService
    this.oauthService.configure(authConfig);

    // For better debugging
    this.oauthService.events.subscribe(e => {
      console.log('OAuth Event:', e);
    });
  }

  async ngOnInit() {
    try {
      // Load the discovery document
      await this.oauthService.loadDiscoveryDocument();

      // Try to handle the OAuth callback
      const isLoggedIn = await this.oauthService.tryLogin({
        onTokenReceived: (info) => {
          console.log('Token received', info);
        }
      });

      if (this.oauthService.hasValidAccessToken()) {
        this.user = this.oauthService.getIdentityClaims();
        console.log('User info:', this.user);
      }
    } catch (error) {
      console.error('Error initializing OAuth', error);
      this.error = 'Error initializing authentication. Please try again.';
    }
  }

  login() {
    try {
      // Clear any existing tokens
      this.oauthService.logOut();

      // Start the login flow
      this.oauthService.initLoginFlow();
    } catch (error) {
      console.error('Login error:', error);
      this.error = 'Error during login. Please try again.';
    }
  }

  logout() {
    this.oauthService.logOut();
    this.user = null;
  }

  isLoggedIn(): boolean {
    const hasValidToken = this.oauthService.hasValidAccessToken();
    if (hasValidToken && !this.user) {
      this.user = this.oauthService.getIdentityClaims();
    }
    return hasValidToken;
  }
}
